        );
        assert_eq!(
            weeks.get(&NaiveDate::from_ymd_opt(2024, 1, 8).unwrap()),
            Some(&20)
        );
    }

    #[test]
    fn formats_oldest_first_with_total_or_no_data() {
        let weeks = BTreeMap::from([
            (NaiveDate::from_ymd_opt(2024, 1, 8).unwrap(), 20),
            (NaiveDate::from_ymd_opt(2024, 1, 1).unwrap(), 10),
        ]);
        assert_eq!(
            format_weekly_bill(&weeks),
            "2024-01-01  10s\n2024-01-08  20s\nTotal  30s\n"
        );
        assert_eq!(format_weekly_bill(&BTreeMap::new()), "(no data)\n");
    }
